import React, { useState, useEffect } from 'react';
import { useAuth } from '../../context/AuthContext';

const CommentSection = ({ articleId }) => {
  const [comments, setComments] = useState([]);
  const [newComment, setNewComment] = useState('');
  const { user } = useAuth();

  useEffect(() => {
    const stored = localStorage.getItem(`comments-${articleId}`);
    if (stored) setComments(JSON.parse(stored));
  }, [articleId]);

  const save = (c) => {
    localStorage.setItem(`comments-${articleId}`, JSON.stringify(c));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!user) {
      alert('Please login to comment');
      return;
    }
    if (newComment.trim()) {
      const comment = {
        user: { name: user.name || user.email },
        text: newComment,
        timestamp: new Date().toISOString(),
      };
      const updated = [...comments, comment];
      setComments(updated);
      save(updated);
      setNewComment('');
    }
  };

  return (
    <div className="comment-section mt-8">
      <h3 className="text-xl font-semibold mb-2">Comments</h3>
      {comments.map((c, idx) => (
        <div key={idx} className="mb-2">
          <span className="font-bold">{c.user.name}</span>: {c.text}
        </div>
      ))}
      <form className="flex gap-2 mt-4" onSubmit={handleSubmit}>
        <input
          type="text"
          value={newComment}
          onChange={(e) => setNewComment(e.target.value)}
          placeholder="Write a comment..."
          className="flex-1 border p-2 rounded"
        />
        <button type="submit" className="bg-blue-600 text-white px-4 rounded">
          Post
        </button>
      </form>
    </div>
  );
};

export default CommentSection;
